const SET=20;
const BANK={};const ALLQ=[];
function wpick(mix){const tot=mix.reduce((a,m)=>a+m[1],0);let r=rnd()*tot;for(const m of mix){if((r-=m[1])<0)return m[0]}return mix[0][0]}
for(const u of UNITS){
const seen=new Set();const qs=[];let guard=0;
while(qs.length<u.n&&guard++<u.n*60){const q=wpick(u.mix)();if(!q||seen.has(q.key))continue;
if(q.opts&&(new Set(q.opts).size!=q.opts.length||q.a<0))continue;
seen.add(q.key);q.id=u.id+"-"+qs.length;q.unit=u.id;qs.push(q)}
u.qs=qs;u.sets=Math.ceil(qs.length/SET);
qs.forEach(q=>{BANK[q.id]=q;ALLQ.push(q)});
}
