function readD(){ // past
 const d=pick(V_DAYS);const pl=pick(V_PLACE.filter(x=>!["home","work","bathroom","bedroom","kitchen"].includes(x[0])));const wt=pick(V_WEATHER.slice(0,8));const f1=pick(RM),f2=pick(RF);const fe=pick([["happy","سعداء"],["tired","متعبين"],["hungry","جائعين"],["busy","مشغولين"],["excited","متحمسين"]]);const mw=pick([["at work","في العمل"],["at the market","في السوق"],["at the hospital","في المستشفى"],["at the mosque","في المسجد"]]);
 const S=[[`Yesterday was ${d[0]}.`,`كان أمس يوم ${d[1]}.`],[`In the morning I was ${pl[2]} ${pl[0]}.`,`في الصباح كنت في ${pl[1]}.`],[`The weather was ${wt[0]}.`,`كان الطقس ${wt[1].split(" / ")[0]}.`],[`My friends ${f1[0]} and ${f2[0]} were there too.`,`صديقاي ${f1[1]} و${f2[1]} كانا هناك أيضاً.`],[`We were very ${fe[0]}.`,`كنا ${fe[1]} جداً.`],[`In the evening I was at home.`,`في المساء كنت في البيت.`],[`My mother wasn't at home. She was ${mw[0]}.`,`لم تكن أمي في البيت. كانت ${mw[1]}.`],[`Today I am at the university, and I am not tired.`,`اليوم أنا في الجامعة، ولست متعباً.`]];
 const Q=[rq("What day was yesterday?",`It was ${d[0]}.`,others(V_DAYS,d[0],3,x=>`It was ${x[0]}.`)),rq("Where was the writer in the morning?",`${cap(pl[2])} ${pl[0]}.`,others(V_PLACE,pl[0],3,x=>`${cap(x[2])} ${x[0]}.`)),rq("What was the weather like?",`It was ${wt[0]}.`,others(V_WEATHER,wt[0],3,x=>`It was ${x[0]}.`)),rq("Who was there too?",`${f1[0]} and ${f2[0]}.`,[`${pick(RM.filter(x=>x!=f1))[0]} and ${f2[0]}.`,`${f1[0]} and ${pick(RF.filter(x=>x!=f2))[0]}.`,"His mother."]),rq("How were they?",`They were ${fe[0]}.`,others(["happy","tired","hungry","busy","excited","sad","angry"],fe[0],3,x=>`They were ${x}.`)),rq("Where was the mother?",cap(mw[0])+".",["At home.",...others(["at work","at the market","at the hospital","at the mosque"],mw[0],2,x=>cap(x)+".")]),{...(()=>{const o=shuf(["No, she wasn't.","Yes, she was."]);return{q:"Was the mother at home?",opts:o,a:o.indexOf("No, she wasn't.")}})()},rq("Where is the writer today?","At the university.",["At home.",`${cap(pl[2])} ${pl[0]}.`,"At work."])];
 return{title:`Yesterday (${d[0]})`,s:S,q:shuf(Q).slice(0,6)}}
const READINGS=[];
for(let i=0;i<60;i++){const g=[readA,readB,readC,readD][i%4];READINGS.push(g())}
READINGS.forEach((r,i)=>{r.id="r"+i;r.html=r.s.map(x=>x[0]).join(" ");r.ar=r.s.map(x=>x[1]).join(" ");r.qs=r.q.map((q,k)=>({t:"read",label:"Reading",color:"var(--green)",prompt:q.q,opts:q.opts,a:q.a,en:q.opts[q.a],ar:null,exp:"",expAr:"",passage:r,id:r.id+"-"+k,unit:"read"}));r.qs.forEach(q=>BANK[q.id]=q)});

/* ================= LISTENING ================= */
const LISTEN=[];
const PAIRN=[[13,30],[14,40],[15,50],[16,60],[17,70],[18,80],[19,90]];
function lHear(){const[s,c]=pickSC({allowIt:true});const neg=rnd()<.5;const form=s.kind=="p"&&rnd()<.5?"short":"full";const ok=sent(s,c,neg,form);
 const wr=[sent(s,c,!neg,form)];const alt=PRON.find(p=>p.en==({He:"She",She:"He",We:"They",They:"We",I:"You",You:"I"}[s.en]));if(alt&&compatible(alt,c))wr.push(sent(alt,c,neg,form));if(alt&&compatible(alt,c))wr.push(sent(alt,c,!neg,form));
 const c2=pick(PERSON_COMP);if(compatible(s,c2))wr.push(sent(s,c2,neg,form));const o=shuf([ok,...uniq3(ok,wr)]);return{t:"listen",label:"What do you hear?",color:"var(--blue)",audio:ok,prompt:"Listen and choose the sentence you hear.",opts:o,a:o.indexOf(ok),en:ok,ar:arS(s,c,neg),exp:"",expAr:"",key:"lh|"+ok}}
function lNum(){const p=pick(PAIRN);const which=rnd()<.5?0:1;const s=pick([...NAMES,PRON[2],PRON[3]]);const kind=rnd()<.5;const mk=n=>kind?`${s.en} is ${n} years old.`:`It's ${n} lira.`;const ok=mk(p[which]);const o=shuf([mk(p[0]),mk(p[1])]);
 return{t:"listen",label:"Numbers: 13 or 30?",color:"var(--gold)",audio:ok,prompt:"Listen carefully: -teen or -ty?",opts:o,a:o.indexOf(ok),en:ok,ar:null,exp:"thirTEEN (13) — stress at the end · THIRty (30) — stress at the start",expAr:"13 النبرة في آخر الكلمة · 30 النبرة في أولها",key:"ln|"+ok}}
function lPast(){const[s,c]=pickSC({comps:[...ADJ,...PLACE]});const tm=pick(TPAST);const past=rnd()<.5;const now=sent(s,c,false).replace(/\.$/,"")+" "+pick(["today","now"])+".";const pst=pastSent(s,c,false,tm);const ok=past?pst:now;const o=shuf([pst,now,pastSent(s,c,true,tm)]);
 return{t:"listen",label:"Present or past?",color:"var(--purple)",audio:ok,prompt:"Listen and choose.",opts:o,a:o.indexOf(ok),en:ok,ar:null,exp:"",expAr:"",key:"lp|"+ok}}
function lReply(){const it=whItem();const wr=[];let g=0;while(wr.length<6&&g++<40){const o=whItem();if(o.cat!=it.cat)wr.push(o.a)}const o=shuf([it.a,...uniq3(it.a,wr)]);
 return{t:"listen",label:"Listen and answer",color:"var(--green)",audio:it.q,prompt:"Listen to the question. Choose the best answer.",opts:o,a:o.indexOf(it.a),en:it.q+" "+it.a,ar:null,exp:it.q+" → "+it.a,expAr:"",key:"lr|"+it.q}}
function lYesNo(){let s,c;do{[s,c]=pickSC({subs:QSUBJ})}while(s.en=="We");const q=qS(s,c);const[p,b]=ansP(s);const P=capI(p);const nb=b=="am"?"'m not":" "+b+"n't";
 const isYes=rnd()<.5;const ok=isYes?`Yes, ${P} ${b}.`:`No, ${P}${nb}.`;
 const prs=[["I","am"],["you","are"],["he","is"],["she","is"],["it","is"],["they","are"]].filter(x=>x[0]!=p);
 const wr=prs.map(([pp,bb])=>isYes?`Yes, ${capI(pp)} ${bb}.`:`No, ${capI(pp)}${bb=="am"?"'m not":" "+bb+"n't"}.`);
 const o=shuf([ok,...uniq3(ok,wr)]);return{t:"listen",label:"Listen and answer",color:"var(--green)",audio:q,prompt:"Listen to the question. Choose the answer with the right pronoun.",opts:o,a:o.indexOf(ok),en:q+" "+ok,ar:null,exp:"Answer with the right pronoun: "+ok,expAr:"انتبه للضمير المناسب في الإجابة",key:"ly|"+q+ok}}
function lDict(){const[s,c]=pickSC({allowIt:true,subs:[...PERSON_SUBJ]});const neg=rnd()<.5;const x=sent(s,c,neg,"full",false);return{t:"order",label:"Listen and build the sentence",color:"var(--gold)",audio:x+".",words:x.split(" "),answer:x,en:x+".",ar:arS(s,c,neg),exp:"",expAr:"",key:"ld|"+x}}
const LMIX=[[lHear,4],[lNum,1.3],[lPast,1.5],[lReply,2],[lYesNo,1.5],[lDict,2]];
{const seen=new Set();let g=0;while(LISTEN.length<400&&g++<20000){const q=wpick(LMIX)();if(!q||seen.has(q.key))continue;if(q.opts&&(new Set(q.opts).size!=q.opts.length||q.a<0))continue;seen.add(q.key);q.id="li-"+LISTEN.length;q.unit="listen";LISTEN.push(q);BANK[q.id]=q}}

