const ABOUT=[["What's your name?","My name is …","ما اسمك؟"],["How old are you?","I am … years old.","كم عمرك؟"],["Where are you from?","I am from …","من أين أنت؟"],["What's your nationality?","I am … (Syrian / Iraqi …)","ما جنسيتك؟"],["What's your job?","I am a student.","ما عملك؟"],["Where are you now?","I am at home. / I am at the university.","أين أنت الآن؟"],["How are you today?","I am fine, thanks. / I am tired.","كيف حالك اليوم؟"],["Who is your best friend?","My best friend is …","من أعز أصدقائك؟"],["What's your teacher's name?","My teacher's name is …","ما اسم معلمك؟"],["Where is your university?","It is in Istanbul.","أين جامعتك؟"],["What day is it today?","It is …","ما اليوم؟"],["What's the weather like today?","It is sunny / cold / rainy.","كيف الطقس اليوم؟"],["Is your family in Istanbul?","No, they aren't. They are in …","هل عائلتك في إسطنبول؟"],["Are you a student?","Yes, I am.","هل أنت طالب؟"],["Is your classroom big?","Yes, it is. / No, it isn't.","هل صفك كبير؟"],["How many students are there in your class?","There are … students.","كم طالباً في صفك؟"],["Is there a café near your house?","Yes, there is. / No, there isn't.","هل يوجد مقهى قرب بيتك؟"],["Where were you yesterday?","I was at …","أين كنت أمس؟"],["Was the lesson easy?","Yes, it was. / No, it wasn't.","هل كان الدرس سهلاً؟"],["What color is your bag?","It is …","ما لون حقيبتك؟"]];
