function vocabList(){return hdr("Vocabulary","كلمات هذه المرحلة مع أمثلة","var(--gold)")+`<div class="tiles">${VOCAB.map(v=>`<button class="tile2" onclick="go('words:${v.id}')" style="--c:var(--gold)"><span class="ti">${v.icon}</span><b>${v.t}</b><span class="ar">${v.ar}</span><small>${v.words.length} words ${"★".repeat(stars["v:"+v.id]||0)}</small></button>`).join("")}</div>`}
